+
+// itemEndLine is the progress line for a setup command or check that has run and ended: the
+// item's name, passed or failed with the exit status, and the wall time in whole seconds,
+// rounded half up.
+func itemEndLine(name string, status int, wallMS int64) string {
+	seconds := (wallMS + 500) / 1000
+	if status == 0 {
+		return fmt.Sprintf("kogen: %s passed (%d s)", name, seconds)
+	}
+	return fmt.Sprintf("kogen: %s failed, exit %d (%d s)", name, status, seconds)
 }

